-- Apply with apply_migration name "kafaa_audit_backfill_p06", in file order. Insert-only (on conflict (id) do nothing); existing rows are never touched. kafaa_* objects only.
select set_config('kafaa.seeding', 'on', true);
on conflict (id) do nothing;
-- live transcription check: the rows this part inserted equal the bundle rows (count and digest); if any id already existed live the count differs and the part rolls back
do $g$ declare n integer; d text; begin
  perform set_config('TimeZone', 'UTC', true);
  select count(*)::int, left(md5(coalesce(string_agg((jsonb_build_object('id', t.id, 'application_id', t.application_id, 'person_id', t.person_id, 'ts', t.ts, 'stage', t.stage, 'note_en', t.note_en, 'note_ar', t.note_ar, 'by_role', t.by_role))::text, '|' order by t.id collate "C"), '')), 16) into n, d from kafaa_application_events t where t.xmin::text = (txid_current() % 4294967296)::text;
  if n is distinct from 161 or d is distinct from 'd7cdb04eae56b5a9' then raise exception 'live transcription check failed for kafaa_application_events: % %', n, d; end if;
end $g$;
